contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 ts) public payable {
        require(address(this).balance >= 10 ether);

        uint256 beforeBalance = address(c).balance;

        // Setup a fresh timestamp precondition via the public entry itself.
        // The first fallback call may or may not revert depending on pastBlockTime
        // and the current block timestamp, so it is done as its own statement.
        bool setupReverted;
        try c.fallback{value: 0}() {
            setupReverted = false;
        } catch {
            setupReverted = true;
        }

        // Record the public pastBlockTime before the deciding call.
        uint256 past = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(address(c).balance == beforeBalance);
        } else {
            assert(block.timestamp > past);
            assert(address(c).balance == beforeBalance + 10 ether || address(c).balance == 0);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(address(this).balance >= 10 ether);

        // Ensure pastBlockTime is at least 1 so the next call is valid.
        uint256 past = c.pastBlockTime();
        if (past == 0) {
            (bool ok0, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature(""));
            require(ok0);
            past = c.pastBlockTime();
        }
        require(past > 0);

        uint256 balBefore = address(c).balance;

        (bool success, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature(""));

        if (success) {
            assert(c.pastBlockTime() == block.timestamp + 1 || c.pastBlockTime() == past);
            assert(address(c).balance == balBefore + 10 ether || address(c).balance == 0);
        } else {
            assert(address(c).balance == balBefore);
            assert(c.pastBlockTime() == past);
        }
    }

    receive() external payable {}
}

