contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 value, uint256 t1, uint256 t2) public payable {
        require(address(this).balance >= value);

        // First call with the caller-supplied timestamp; its success/revert is ignored
        // (state only advances on success, and the rule below is about the final call).
        (bool ok1, ) = address(c).call{value: value}(abi.encodeWithSignature(""));
        ok1;
        uint256 pt1 = c.pastBlockTime();

        // Second call observes the same msg.sender and the timestamp advanced by the first call.
        (bool ok2, ) = address(c).call{value: value}(abi.encodeWithSignature(""));
        uint256 pt2 = c.pastBlockTime();

        // Comparing the prior successful-call timestamp pt1 with the current time is not enough
        // (block.timestamp may equal pt1 - 1 exactly after a success). Compare it directly to the
        // contract's own notion of validity instead.
        assert(ok2 == (t1 > pt1));
    }

    receive() external payable {}
}

