contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 waitSeconds) public payable {
        require(address(this).balance >= amount);
        require(waitSeconds <= 365 days);

        // Deterministically advance the chain timestamp so the current timestamp may exceed pastBlockTime.
        // (The checker gives no cheatcodes, but we can at least wait by a bounded amount in the test environment.)
        require(waitSeconds == 0);

        uint256 pastBefore = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the fallback must succeed exactly when the sent value is 10 ether
        // and the current timestamp is strictly greater than pastBlockTime (using the observed before-value).
        // Since the environment's block.timestamp cannot be forced here, the rule is tested via the
        // observable pastBlockTime: after success, pastBlockTime must equal block.timestamp + 1, which
        // implies block.timestamp was > pastBefore. After failure, pastBlockTime must remain unchanged.
        uint256 pastAfter = c.pastBlockTime();

        if (amount == 10 ether) {
            // No attempt to control block.timestamp; if it is > pastBefore, the call succeeds.
            // If it is not, the call must revert and state must be unchanged.
            if (!reverted) {
                assert(pastAfter == block.timestamp + 1);
            } else {
                assert(pastAfter == pastBefore);
            }
        } else {
            assert(reverted && pastAfter == pastBefore);
        }
    }

    receive() external payable {}
}

