    constructor(C _c) { c = _c; }

    function run(uint amount, uint timestamp, uint blockNumber) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);
        require(timestamp > c.pastBlockTime());

        uint balBefore = address(c).balance;
        uint senderBefore = address(this).balance;

        (bool reverted, ) = address(c).call{value: amount}("");

        uint balAfter = address(c).balance;
        uint senderAfter = address(this).balance;

        if (reverted) {
            assert(balAfter == balBefore && senderAfter == senderBefore);
        } else {
            if (blockNumber % 15 == 0) {
                assert(balAfter == 0 && senderAfter == senderBefore + balBefore);
            } else {
                assert(balAfter == balBefore + amount && senderAfter == senderBefore - amount);
            }
        }
    }

    receive() external payable {}
}

