contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 waitSeconds) public payable {
        require(address(this).balance >= amount);

        uint256 beforePast = c.pastBlockTime();

        // Try to satisfy the timestamp condition by advancing the block timestamp
        // (bytes32 cast allows the timestamp to be increased by waiting).
        if (waitSeconds > 0) {
            assembly {
                let newTs := add(timestamp(), waitSeconds)
                if gt(newTs, timestamp()) {
                    pop(call(0, 0, 0, 0, 0, 0, 0))
                }
            }
        }

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterPast = c.pastBlockTime();

        bool timestampOk = block.timestamp > beforePast;
        bool valueOk = amount == 10 ether;

        assert(reverted == !(timestampOk && valueOk));
        if (!reverted) {
            assert(afterPast == beforePast + 1);
        } else {
            assert(afterPast == beforePast);
        }
    }

    receive() external payable {}
}

