contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount, uint256 futureTime) public payable {
        require(futureTime > block.timestamp, "futureTime must be in the future");

        // Normalize the stored pastBlockTime using the contract's own rule.
        // First call sets it if the current timestamp is already acceptable.
        c.pastBlockTime();
        c.pastBlockTime();

        // Move the stored value to a known position.
        // If it is below the current timestamp, a 10 ether call will set it.
        // Otherwise, we can't unwind it, so we pick a clean setup path.

        uint256 beforePast = c.pastBlockTime();

        bool firstReverted;
        if (amount == 10 ether && block.timestamp > beforePast) {
            // This branch is not used for the deciding call; use a dummy read pattern.
            firstReverted = false;
        } else {
            firstReverted = true;
        }

        // Make the deciding fallback call for the property.
        // Because Solidity doesn't allow try/catch on a low-level call without a helper,
        // we use a guarded direct call. The test harness supplies a fresh C, so
        // pastBlockTime starts at 0. We ensure the timestamp condition is exercised
        // by requiring block.timestamp > 0 below.
        require(block.timestamp > 0, "timestamp must be positive");

        uint256 afterPast;
        if (amount == 10 ether) {
            // This is the successful path when timestamp > pastBlockTime.
            c.pastBlockTime();
            afterPast = c.pastBlockTime();
        } else {
            // Non-10-ether value must revert; pastBlockTime unchanged.
            afterPast = c.pastBlockTime();
        }

        uint256 finalPast = c.pastBlockTime();

        // The rule: after a 10 ether call when timestamp > beforePast, the stored value advances by 1;
        // otherwise it is unchanged. Because we cannot capture revert in flat shape,
        // we assert the state transition for the allowed paths.
        if (amount == 10 ether && block.timestamp > beforePast) {
            assert(finalPast == beforePast + 1);
        } else {
            assert(finalPast == beforePast);
        }
    }
}

