contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint newTimestamp) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);
        require(newTimestamp > 0);

        // advance pastBlockTime as in the contract's fallback
        uint oldPast = c.pastBlockTime();
        // satisfy block.timestamp > pastBlockTime by choosing newTimestamp above oldPast
        require(newTimestamp > oldPast);

        // Set the state so that pastBlockTime is ahead of the current timestamp
        // and then the fallback call will be invalid unless timestamp catches up
        // (we do this via vm-free means by relying on pastBlockTime getter)
        // To cause a revert, call fallback when the timestamp condition fails.

        // First, drive c through a valid path to ensure state is set in a way
        // that the next call's revert is due to the timestamp rule, not something else.
        bool firstReverted;
        try c.fallback{value: amount}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Now, if the first call succeeded, pastBlockTime was set to block.timestamp + 1.
        // Calling fallback again in the same block would revert because
        // block.timestamp is not greater than pastBlockTime.
        // We test that the second call reverts exactly when the first succeeded.
        bool secondReverted;
        try c.fallback{value: amount}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: if the first call succeeds, the second call in the same
        // transaction must revert, because pastBlockTime was set to current timestamp + 1.
        // Conversely, if the first call reverts, the second may or may not revert,
        // but the rule we assert is the implication: first success -> second revert.
        assert(!firstReverted || secondReverted);
    }

    receive() external payable {}
}

