contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 ts) public payable {
        require(address(this).balance >= 10 ether);
        require(ts > block.timestamp);

        // Force c's pastBlockTime to a value >= ts so the fallback's
        // `require(block.timestamp > pastBlockTime)` must fail.
        // We can create this state only by first making a successful fallback call.
        // If that first call is impossible (e.g. ts is too close), we adapt by
        // requiring the precondition and using the current value instead.
        bool firstReverted;
        uint256 oldPast;
        try c.fallback{value: 10 ether}() {
            firstReverted = false;
            oldPast = c.pastBlockTime();
        } catch {
            firstReverted = true;
            oldPast = c.pastBlockTime();
        }

        // The deciding call: exactly 10 ether, same as the first.
        bool reverted;
        uint256 before = c.pastBlockTime();
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 after_ = c.pastBlockTime();

        // General rule: a call reverts if and only if it would advance
        // pastBlockTime to a value that is not strictly greater than the
        // current block.timestamp AND the contract does not already have
        // enough balance to satisfy the 10 ether requirement.
        // In this test we ensure enough balance, so the timestamp rule applies:
        // the fallback succeeds exactly when `block.timestamp > pastBlockTime`.
        // Here, due to the first call, pastBlockTime is either oldPast (if the
        // first call reverted) or max(oldPast, block.timestamp+1) (if it succeeded),
        // so for all ts > block.timestamp the timestamp condition is true only
        // when the first call succeeded, and false when it reverted.
        // Thus: if the first call reverted (oldPast >= block.timestamp), the
        // second must also revert; if it succeeded (oldPast < block.timestamp),
        // the second must succeed and set pastBlockTime = block.timestamp + 1.
        if (!firstReverted) {
            assert(!reverted && after_ == block.timestamp + 1);
        } else {
            assert(reverted && after_ == before);
        }
    }

    receive() external payable {}
}

