        // If reverted, pastBlockTime must equal before (no state change), assuming no other state change.
        uint afterVal = c.pastBlockTime();

        // General rule: If the call succeeded, it must be that amount == 10 ether and the new pastBlockTime is strictly greater than the old one.
        // If it reverted, no state change occurred (pastBlockTime unchanged).
        // Also, for success, amount must be exactly 10 ether.
        // Combined: (reverted == false) implies (amount == 10 ether AND afterVal > before).
        // And (reverted == true) implies (afterVal == before).
        assert((reverted || (amount == 10 ether && afterVal > before)) && (!reverted || afterVal == before));
    }

    receive() external payable {}
}

