contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 newTimestamp) public payable {
        require(address(this).balance >= amount);

        // Set up a known pastBlockTime by making a successful call first.
        // First call needs to satisfy block.timestamp > pastBlockTime (initially 0) and 10 ether.
        // We cannot warp, so we rely on block.timestamp being > 0 in a real execution.
        // To be safe for any environment, only do setup if we can and value is enough.
        // Actually we need a controlled before-state. Use a view-free approach:
        // We make the deciding call first, but we need a before value.
        // Read pastBlockTime before any call.
        uint256 before = c.pastBlockTime();
        uint256 balBefore = address(this).balance;

        // The deciding call: send `amount` wei to c's fallback (with empty calldata).
        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The fallback requires msg.value == 10 ether, so amount must be 10 ether to not revert on that check.
        // It also requires block.timestamp > pastBlockTime.
        // We cannot control block.timestamp, so the rule must be about whether it reverts or not given
        // the current block.timestamp and the before value.
        // General rule: if amount == 10 ether and block.timestamp > before, then it should succeed
        // (ignoring the block.number % 15 branch which only affects balance transfer, not pastBlockTime or revert).
        // and pastBlockTime should become block.timestamp + 1.
        // Otherwise it should revert and pastBlockTime unchanged.
        if (amount == 10 ether && block.timestamp > before) {
            assert(!reverted && c.pastBlockTime() == block.timestamp + 1);
        } else {
            assert(reverted && c.pastBlockTime() == before);
            // Also Ether should not move on revert (except gas), but balance check might be tricky
            // due to potential block.number % 15 transfer. On revert, no transfer happens.
            // We can check that c's balance didn't increase by amount.
            assert(address(c).balance <= balBefore);
        }
    }

    receive() external payable {}
}

