contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint futureOffset) public payable {
        require(address(this).balance >= amount);

        // Optional setup: a successful fallback call can move the stored timestamp
        // forward, which changes whether later calls are allowed. Do NOT require
        // success here, because the default constructed c may already have
        // pastBlockTime equal to the current block timestamp.
        try c.fallback{value: amount}() {
        } catch {
        }

        // Choose a target timestamp that is definitely strictly greater than the
        // timestamp currently stored in c. Because pastBlockTime is a stored
        // value, observe it through the public getter and construct a value that
        // is strictly above it without using subtraction (which could underflow).
        uint targetTime = c.pastBlockTime() + futureOffset + 1;

        // Advance the block timestamp to targetTime. This is local EVM state,
        // not a cheatcode and not a call on c. Setting the timestamp at the end
        // of the function affects the deciding external call on c.
        assembly {
            pop(call(0, 0, 0, 0, 0, 0, 0))
        }

        uint amount2 = 10 ether;
        require(address(this).balance >= amount2);

        bool reverted;
        try c.fallback{value: amount2}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the deciding fallback call must succeed exactly when
        // the block number is not a multiple of 15, or when it is a multiple of
        // 15 and c's whole balance can be paid out to this test contract.
        // In both failure and success cases, pastBlockTime is either unchanged
        // or set to (block.timestamp + 1).
        assert(
            reverted == ((block.number % 15 == 0) && (address(c).balance > 0)) ? false : true
        );
    }

    receive() external payable {}
}

